source='''from collections import Counter, deque

def _components(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    out = []
    for r in range(h):
        for c in range(w):
            if (r, c) in seen:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                x, y = q.popleft()
                cells.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    a, b = x + dx, y + dy
                    if 0 <= a < h and 0 <= b < w and (a, b) not in seen and grid[a][b] == color:
                        seen.add((a, b))
                        q.append((a, b))
            out.append((color, cells))
    return out

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    comps = _components(grid)
    markers = []
    for i, (color, cells) in enumerate(comps):
        if color == bg:
            continue
        s = set(cells)
        r0, r1 = min(r for r, c in s), max(r for r, c in s)
        c0, c1 = min(c for r, c in s), max(c for r, c in s)
        # An L made from a vertical stem and a horizontal arm, with the
        # vertical stem ending at the arm's row.
        for corner_c in (c0, c1):
            for corner_r in (r0, r1):
                for h_end in (c0, c1):
                    if h_end == corner_c:
                        continue
                    shape = ({(r, corner_c) for r in range(r0, r1 + 1)} |
                             {(corner_r, c) for c in range(c0, c1 + 1)})
                    # In these patterns, the horizontal arm joins a vertical
                    # stem at one of its endpoints (the elbow).
                    if corner_r in (r0, r1) and s == shape:
                        vertical_len = r1-r0+1
                        horizontal_len = c1-c0+1
                        if vertical_len >= 3 and horizontal_len >= 3:
                            markers.append((len(s), i, color, corner_r, corner_c, 1 if h_end > corner_c else -1))
    if not markers:
        return [row[:] for row in grid]
    _, mi, marker_color, cr, cc, hdir = max(markers)
    # Recolor the closest separate object lying across the vertical stem,
    # opposite the direction in which the L's horizontal arm points.
    candidates = []
    for j, (color, cells) in enumerate(comps):
        if j == mi or color == bg:
            continue
        if hdir > 0 and not all(c < cc for r, c in cells):
            continue
        if hdir < 0 and not all(c > cc for r, c in cells):
            continue
        dist = min(abs(r-cr) + abs(c-cc) for r, c in cells)
        candidates.append((dist, j))
    if not candidates:
        return [row[:] for row in grid]
    _, target = min(candidates)
    out = [row[:] for row in grid]
    for r, c in comps[target][1]:
        out[r][c] = marker_color
    return out

if __name__ == "__main__":
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
